'use client';

import { cn } from '@/lib/utils';
import {
  type AnswerInput,
  type ApproveInput,
  type AutocompleteSource,
  type ChatQueue as ChatQueueModel,
  type ChatStatus,
  type EditSubmitInput,
  type MessageActionInput,
  type MessageUsageInfo,
  type RejectInput,
  type SkipInput,
  type TranscriptSource,
  useChatTranscript,
} from '@dudousxd/nestjs-agent-react';
import type { UIMessage } from 'ai';
import type { ReactNode } from 'react';
import { ChatCommandPalette, type ChatSuggestion } from './chat-command-palette';
import { ChatComposer } from './chat-composer';
import { type ChatContextSource, ChatContextStrip } from './chat-context-strip';
import { type ChatMode, ChatModePills } from './chat-mode-pills';
import { ChatQueue } from './chat-queue';
import type { RenderToolPartFn } from './chat-tool-group';
import { ChatTranscriptView } from './chat-transcript';
import { ChatWelcome } from './chat-welcome';

export interface AgentChatProps {
  /** `chat.messages` and `chat.status` from `useAgentChat` — or any AI SDK v7 chat. */
  messages: UIMessage[];
  status: ChatStatus;
  /**
   * Send a message — `(text) => chat.sendMessage({ text })`. Mid-turn the composer still sends, and
   * `useAgentChat` queues it (see `queue`).
   */
  onSubmit: (text: string) => void;
  /**
   * `chat.queue` — messages sent mid-turn, drawn under the transcript as waiting bubbles with a
   * remove control, and a resume control while the queue is paused.
   */
  queue?: ChatQueueModel;
  /** Cancel the turn in flight — `chat.cancel`. Without it the composer offers no stop. */
  onStop?: () => void | Promise<void>;
  editable?: boolean;
  onEditSubmit?: (input: EditSubmitInput) => void | Promise<void>;
  onFork?: (input: MessageActionInput) => void | Promise<void>;
  regeneratable?: boolean;
  onRegenerate?: (input: MessageActionInput) => void | Promise<void>;
  getUsage?: (message: UIMessage) => MessageUsageInfo | null;
  getCreatedAt?: (message: UIMessage) => string | null;
  followUps?: string[];

  /**
   * Settle a parked question set — `chat.answer`. Default: the enclosing `<AgentProvider>`'s backend,
   * so the form works with nothing passed; `null` leaves question sets as plain tool calls.
   */
  onAnswer?: ((input: AnswerInput) => void | Promise<void>) | null;
  onSkip?: ((input: SkipInput) => void | Promise<void>) | null;
  /** Settle a tool call parked on a human — `chat.approve` / `chat.reject`. Default: the backend's. */
  onApprove?: ((input: ApproveInput) => void | Promise<void>) | null;
  onReject?: ((input: RejectInput) => void | Promise<void>) | null;

  welcomeTitle?: ReactNode;
  welcomeDescription?: ReactNode;
  welcomeMark?: ReactNode;

  modes?: ChatMode[];
  mode?: string | null;
  onModeChange?: (mode: ChatMode) => void;

  contextSources?: ChatContextSource[];
  contextTotal?: number;
  onAddContext?: () => void;

  suggestions?: ChatSuggestion[];
  onSuggestionSelect?: (suggestion: ChatSuggestion) => void;
  onDismissSuggestions?: () => void;

  /**
   * What the composer completes, and after which character — `/` for a skill, `@` for a mention.
   * Nothing here knows what a source offers; adding a second trigger is another entry in the array.
   */
  autocompleteSources?: readonly AutocompleteSource[];
  onAutocompleteError?: (error: unknown, source: AutocompleteSource) => void;

  onAttach?: () => void;
  /** Left of the submit control — a model picker, a temperature toggle. */
  composerTrailing?: ReactNode;
  placeholder?: string;

  renderText?: (text: string, ctx: { isStreaming: boolean }) => ReactNode;
  reasoningLabel?: ReactNode;
  renderSourceIcon?: (source: TranscriptSource) => ReactNode;
  onSourceClick?: (source: TranscriptSource) => void;
  sourceChips?: boolean;
  /** Draw a tool call yourself — it arrives with whatever human decision it is parked on. */
  renderToolPart?: RenderToolPartFn;
  className?: string;
}

/**
 * The whole chat surface over `useChatTranscript`: a welcome state until the first message, then a
 * scrolling transcript with the composer docked beneath it. Every branch it makes is a boolean the
 * model already computed.
 */
export function AgentChat({
  messages,
  status,
  onSubmit,
  queue,
  onStop,
  editable,
  onEditSubmit,
  onFork,
  regeneratable,
  onRegenerate,
  getUsage,
  getCreatedAt,
  followUps,
  onAnswer,
  onSkip,
  onApprove,
  onReject,
  welcomeTitle = 'What should I look through?',
  welcomeDescription,
  welcomeMark,
  modes,
  mode = null,
  onModeChange,
  contextSources,
  contextTotal,
  onAddContext,
  suggestions,
  onSuggestionSelect,
  onDismissSuggestions,
  autocompleteSources,
  onAutocompleteError,
  onAttach,
  composerTrailing,
  placeholder,
  renderText,
  reasoningLabel,
  renderSourceIcon,
  onSourceClick,
  sourceChips = false,
  renderToolPart,
  className,
}: AgentChatProps) {
  const transcript = useChatTranscript({
    messages,
    status,
    sources: true,
    onStop,
    editable,
    onEditSubmit,
    onFork,
    regeneratable,
    onRegenerate,
    getUsage,
    getCreatedAt,
    followUps,
    onAnswer,
    onSkip,
    onApprove,
    onReject,
    ...(queue !== undefined
      ? { queue: { items: queue.items, paused: queue.paused, remove: queue.remove } }
      : {}),
  });

  const composer = (
    <ChatComposer
      onSubmit={onSubmit}
      stop={transcript.stop}
      placeholder={placeholder}
      onAttach={onAttach}
      trailing={composerTrailing}
      {...(autocompleteSources !== undefined ? { autocompleteSources } : {})}
      {...(onAutocompleteError !== undefined ? { onAutocompleteError } : {})}
      overlay={
        suggestions && onSuggestionSelect ? (
          <ChatCommandPalette
            suggestions={suggestions}
            onSelect={onSuggestionSelect}
            onClose={onDismissSuggestions}
          />
        ) : null
      }
      footer={
        contextSources ? (
          <ChatContextStrip sources={contextSources} total={contextTotal} onAdd={onAddContext} />
        ) : null
      }
    />
  );

  const modePills =
    modes && modes.length > 0 ? (
      <ChatModePills modes={modes} value={mode} onSelect={onModeChange} />
    ) : null;

  if (transcript.showEmptyState) {
    return (
      <div className={cn('flex h-full flex-col justify-center', className)}>
        <ChatWelcome
          title={welcomeTitle}
          description={welcomeDescription}
          mark={welcomeMark}
          footer={modePills}
        >
          {composer}
        </ChatWelcome>
      </div>
    );
  }

  return (
    <div className={cn('flex h-full min-h-0 flex-col', className)}>
      <ChatTranscriptView
        transcript={transcript}
        sourceChips={sourceChips}
        renderText={renderText}
        reasoningLabel={reasoningLabel}
        renderSourceIcon={renderSourceIcon}
        onSourceClick={onSourceClick}
        renderToolPart={renderToolPart}
        followUps={followUps}
        onFollowUpSelect={onSubmit}
      />
      <div className="mx-auto w-full max-w-3xl shrink-0 px-4 pb-4">
        <ChatQueue
          items={transcript.queued}
          paused={transcript.queuePaused}
          {...(queue !== undefined ? { onResume: queue.resume } : {})}
          className="pb-3"
        />
        {composer}
        {modePills ? <div className="pt-3">{modePills}</div> : null}
      </div>
    </div>
  );
}

'use client';

import { cn } from '@/lib/utils';
import type { ChatTranscript, TranscriptSource } from '@dudousxd/nestjs-agent-react';
import type { ReactNode } from 'react';
import { ChatFollowUps } from './chat-follow-ups';
import { ChatMessage } from './chat-message';
import type { RenderToolPartFn } from './chat-tool-group';
import { ArrowDownIcon } from './icons';

export interface ChatTranscriptProps {
  /** The whole model. Every branch below is one of its booleans. */
  transcript: ChatTranscript;
  renderText?: (text: string, ctx: { isStreaming: boolean }) => ReactNode;
  reasoningLabel?: ReactNode;
  renderSourceIcon?: (source: TranscriptSource) => ReactNode;
  onSourceClick?: (source: TranscriptSource) => void;
  sourceChips?: boolean;
  /** Draw a tool call yourself — it arrives with whatever human decision it is parked on. */
  renderToolPart?: RenderToolPartFn;
  /** The same array handed to `useChatTranscript`; whether to show it is `showFollowUps`. */
  followUps?: string[];
  onFollowUpSelect?: (text: string) => void;
  emptyState?: ReactNode;
  typingIndicator?: ReactNode;
  className?: string;
}

/** The scrolling transcript: windowed messages, a typing line, follow-ups, and a jump-to-latest. */
export function ChatTranscriptView({
  transcript,
  renderText,
  reasoningLabel,
  renderSourceIcon,
  onSourceClick,
  sourceChips = false,
  renderToolPart,
  followUps,
  onFollowUpSelect,
  emptyState,
  typingIndicator = 'Thinking…',
  className,
}: ChatTranscriptProps) {
  if (transcript.showEmptyState && emptyState) {
    return <>{emptyState}</>;
  }

  const messageSlots = {
    renderText,
    reasoningLabel,
    renderSourceIcon,
    onSourceClick,
    sourceChips,
    renderToolPart,
  };

  return (
    <div
      data-slot="chat-transcript"
      className={cn('relative flex min-h-0 flex-1 flex-col', className)}
    >
      <div
        {...transcript.scroll.getContainerProps()}
        data-slot="chat-transcript-scroller"
        className="flex-1 overflow-y-auto scroll-smooth px-4 py-4"
      >
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-5">
          {transcript.window.canLoadEarlier ? (
            <button
              type="button"
              onClick={transcript.window.loadEarlier}
              className={cn(
                'mx-auto rounded-full border border-border bg-background px-3 py-1.5',
                'text-xs text-muted-foreground transition-colors outline-none hover:bg-accent',
                'focus-visible:ring-[3px] focus-visible:ring-ring/50',
              )}
            >
              Load {transcript.window.hiddenCount} earlier
            </button>
          ) : null}

          {transcript.items.map((item) => (
            <ChatMessage key={item.id} item={item} {...messageSlots} />
          ))}

          {transcript.showTypingIndicator ? (
            <p className="text-sm text-muted-foreground" aria-live="polite">
              {typingIndicator}
            </p>
          ) : null}

          {transcript.showFollowUps && followUps && onFollowUpSelect ? (
            <ChatFollowUps items={followUps} onSelect={onFollowUpSelect} />
          ) : null}
        </div>
      </div>

      {transcript.scroll.showJumpToLatest ? (
        <button
          type="button"
          onClick={transcript.scroll.scrollToBottom}
          aria-label="Jump to latest"
          className={cn(
            'absolute bottom-4 left-1/2 flex size-9 -translate-x-1/2 items-center justify-center',
            'rounded-full border border-border bg-background text-foreground shadow-md',
            'transition-colors outline-none hover:bg-accent',
            'focus-visible:ring-[3px] focus-visible:ring-ring/50',
          )}
        >
          <ArrowDownIcon className="size-4" />
        </button>
      ) : null}
    </div>
  );
}

'use client';

import { cn } from '@/lib/utils';
import type {
  TranscriptBlock,
  TranscriptItem,
  TranscriptSource,
  TranscriptSourcesBlock,
  TranscriptUiBlock,
} from '@dudousxd/nestjs-agent-react';
import type { ReactNode } from 'react';
import { ChatElicitation } from './chat-elicitation';
import { ChatFiles } from './chat-files';
import { ChatReasoning } from './chat-reasoning';
import { ChatSourceChips, ChatSources } from './chat-sources';
import { ChatToolGroup, type RenderToolPartFn } from './chat-tool-group';
import { BranchIcon, CheckIcon, CopyIcon, PencilIcon, RefreshIcon } from './icons';

type BodyBlock = Exclude<TranscriptBlock, TranscriptSourcesBlock>;

function isSourcesBlock(block: TranscriptBlock): block is TranscriptSourcesBlock {
  return block.kind === 'sources';
}

export interface ChatMessageProps {
  /** One item off `transcript.items` — every value and every action below comes from it. */
  item: TranscriptItem;
  /** Render the prose. Pass a markdown renderer here; plain text is the default. */
  renderText?: (text: string, ctx: { isStreaming: boolean }) => ReactNode;
  reasoningLabel?: ReactNode;
  /** Override the reasoning duration label. Omitted → derived from the block (see `ChatReasoning`). */
  reasoningDuration?: ReactNode;
  renderSourceIcon?: (source: TranscriptSource) => ReactNode;
  onSourceClick?: (source: TranscriptSource) => void;
  /** Repeat the origins as chips under the answer body. */
  sourceChips?: boolean;
  /** Draw a tool call yourself — a rendered result, a diff, a map. Falls back to the tool card. */
  renderToolPart?: RenderToolPartFn;
  /** Draw a component the server pushed (a `ui` stream frame) from your own registry. Omitted → not drawn. */
  renderUi?: (block: TranscriptUiBlock) => ReactNode;
  className?: string;
}

export function ChatMessage({
  item,
  renderText,
  reasoningLabel,
  reasoningDuration,
  renderSourceIcon,
  onSourceClick,
  sourceChips = false,
  renderToolPart,
  renderUi,
  className,
}: ChatMessageProps) {
  if (item.edit.isEditing) {
    return <EditingBubble item={item} className={className} />;
  }

  // Provenance reads as a preamble to the answer rather than a footnote inside it, so the sources
  // blocks are hoisted above the body wherever the retrieval part happens to sit in the message.
  const sources = item.blocks.filter(isSourcesBlock);
  const body = item.blocks.filter((block): block is BodyBlock => block.kind !== 'sources');

  return (
    <article
      data-role={item.role}
      data-streaming={item.isStreaming ? 'true' : undefined}
      className={cn('group/message flex flex-col gap-2', item.isUser && 'items-end', className)}
    >
      {sources.map((block) => (
        <ChatSources
          key={block.key}
          block={block}
          className="w-full"
          renderSourceIcon={renderSourceIcon}
          onSourceClick={onSourceClick}
        />
      ))}

      <div
        className={cn(
          'flex max-w-full flex-col gap-2.5',
          item.isUser
            ? 'rounded-2xl rounded-br-md bg-muted px-4 py-2.5 text-foreground'
            : 'w-full rounded-2xl border border-border bg-card px-4 py-3 text-card-foreground',
        )}
      >
        {body.map((block) => {
          if (block.kind === 'text') {
            return (
              <div
                key={block.key}
                className="text-sm leading-relaxed whitespace-pre-wrap text-pretty"
              >
                {renderText
                  ? renderText(block.text, { isStreaming: block.isStreaming })
                  : block.text}
              </div>
            );
          }
          if (block.kind === 'reasoning') {
            return (
              <ChatReasoning
                key={block.key}
                block={block}
                label={reasoningLabel}
                duration={reasoningDuration}
              />
            );
          }
          if (block.kind === 'elicitation') {
            return <ChatElicitation key={block.key} block={block} />;
          }
          if (block.kind === 'files') {
            return <ChatFiles key={block.key} block={block} />;
          }
          if (block.kind === 'ui') {
            return renderUi ? (
              <div key={block.key} data-slot="ui" data-component={block.component}>
                {renderUi(block)}
              </div>
            ) : null;
          }
          return <ChatToolGroup key={block.key} block={block} renderToolPart={renderToolPart} />;
        })}

        {sourceChips
          ? sources.map((block) => (
              <ChatSourceChips
                key={`${block.key}-chips`}
                block={block}
                onSourceClick={onSourceClick}
              />
            ))
          : null}
      </div>

      <MessageActions item={item} />
    </article>
  );
}

function MessageActions({ item }: { item: TranscriptItem }) {
  const hasAction =
    item.copy.available || item.edit.available || item.fork.available || item.regenerate.available;
  if (!hasAction && !item.usage && !item.timestamp) {
    return null;
  }

  return (
    <div
      data-actions-for={item.role}
      className={cn(
        'flex items-center gap-0.5 text-muted-foreground',
        // The row stays reachable by keyboard while it is visually quiet.
        'opacity-0 transition-opacity focus-within:opacity-100 group-hover/message:opacity-100',
      )}
    >
      {item.copy.available ? (
        <ActionButton
          onClick={item.copy.copy}
          label={item.copy.copied ? 'Copied' : 'Copy message'}
          icon={item.copy.copied ? <CheckIcon /> : <CopyIcon />}
        />
      ) : null}
      {item.edit.available ? (
        <ActionButton onClick={item.edit.start} label="Edit and resend" icon={<PencilIcon />} />
      ) : null}
      {item.fork.available ? (
        <ActionButton onClick={item.fork.run} label="Fork from here" icon={<BranchIcon />} />
      ) : null}
      {item.regenerate.available ? (
        <ActionButton onClick={item.regenerate.run} label="Regenerate" icon={<RefreshIcon />} />
      ) : null}
      {item.usage ? (
        <span
          className="ml-1 text-xs tabular-nums"
          title={`Input ${item.usage.inputTokens.toLocaleString()} · output ${item.usage.outputTokens.toLocaleString()} tokens`}
        >
          {item.usage.costLabel} · {item.usage.tokensLabel}
        </span>
      ) : null}
      {item.timestamp ? (
        <time
          dateTime={item.timestamp.iso}
          title={item.timestamp.absolute}
          className="ml-1 text-xs"
        >
          {item.timestamp.relative}
        </time>
      ) : null}
    </div>
  );
}

interface ActionButtonProps {
  onClick: () => void;
  label: string;
  icon: ReactNode;
}

function ActionButton({ onClick, label, icon }: ActionButtonProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={label}
      title={label}
      className={cn(
        'flex size-7 items-center justify-center rounded-md [&_svg]:size-3.5',
        'transition-colors outline-none hover:bg-accent hover:text-foreground',
        'focus-visible:ring-[3px] focus-visible:ring-ring/50',
      )}
    >
      {icon}
    </button>
  );
}

function EditingBubble({ item, className }: { item: TranscriptItem; className?: string }) {
  const textareaProps = item.edit.getTextareaProps();
  return (
    <div data-editing="true" className={cn('flex flex-col items-end gap-2', className)}>
      <textarea
        {...textareaProps}
        aria-label="Edit message"
        rows={Math.min(8, item.edit.draft.split('\n').length + 1)}
        className={cn(
          'w-full resize-none rounded-2xl border border-border bg-card px-4 py-2.5',
          'text-sm text-foreground outline-none',
          'focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/40',
        )}
      />
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={item.edit.cancel}
          className={cn(
            'rounded-lg px-3 py-1.5 text-sm text-muted-foreground',
            'transition-colors outline-none hover:bg-accent hover:text-foreground',
            'focus-visible:ring-[3px] focus-visible:ring-ring/50',
          )}
        >
          Cancel
        </button>
        <button
          type="button"
          onClick={item.edit.save}
          disabled={!item.edit.canSave}
          className={cn(
            'rounded-lg bg-foreground px-3 py-1.5 text-sm text-background',
            'transition-opacity outline-none hover:opacity-90',
            'focus-visible:ring-[3px] focus-visible:ring-ring/50',
            'disabled:pointer-events-none disabled:opacity-40',
          )}
        >
          Resend
        </button>
      </div>
    </div>
  );
}

'use client';

import { cn } from '@/lib/utils';
import {
  type TranscriptReasoningBlock,
  formatElapsed,
  useElapsed,
} from '@dudousxd/nestjs-agent-react';
import type { ReactNode } from 'react';
import { ChevronDownIcon, ClockIcon } from './icons';

export interface ChatReasoningProps {
  /** A `reasoning` block off `item.blocks`. Its open state and toggle belong to the model. */
  block: TranscriptReasoningBlock;
  label?: ReactNode;
  /**
   * How long the thinking took. Omitted → derived: a ticking count while the block streams, then
   * the duration the block carries (`block.durationMs`, the server's measurement, live or reloaded).
   * Pass `null` to show none.
   */
  duration?: ReactNode;
  children?: ReactNode;
  className?: string;
}

/** A named, collapsible segment of the answer. Open while it streams, folded once the answer lands. */
export function ChatReasoning({
  block,
  label = 'Reasoning',
  duration,
  children,
  className,
}: ChatReasoningProps) {
  const regionId = `${block.key}-body`;
  const elapsed = useElapsed(block.isStreaming);
  const derivedMs = block.isStreaming ? elapsed : block.durationMs;
  const shownDuration =
    duration !== undefined ? duration : derivedMs !== null ? formatElapsed(derivedMs) : null;

  return (
    <div
      data-slot="chat-reasoning"
      className={cn('rounded-xl border border-border/70 bg-muted/30', className)}
    >
      <button
        type="button"
        onClick={() => block.toggle()}
        aria-expanded={block.isOpen}
        aria-controls={regionId}
        className={cn(
          'flex w-full items-center gap-2 rounded-xl px-3 py-2 text-left',
          'transition-colors outline-none hover:bg-accent/50',
          'focus-visible:ring-[3px] focus-visible:ring-ring/50',
        )}
      >
        <span
          aria-hidden="true"
          className={cn(
            'size-1.5 shrink-0 rounded-full bg-muted-foreground',
            block.isStreaming && 'animate-pulse bg-foreground',
          )}
        />
        <span className="min-w-0 flex-1 truncate text-sm font-medium text-foreground">{label}</span>
        {shownDuration ? (
          <span className="inline-flex shrink-0 items-center gap-1 text-xs text-muted-foreground tabular-nums">
            <ClockIcon className="size-3.5" />
            {shownDuration}
          </span>
        ) : null}
        <ChevronDownIcon
          className={cn(
            'size-4 shrink-0 text-muted-foreground transition-transform',
            block.isOpen && 'rotate-180',
          )}
        />
      </button>
      {block.isOpen ? (
        <div
          id={regionId}
          className="px-3 pb-3 text-sm leading-relaxed whitespace-pre-wrap text-muted-foreground"
        >
          {children ?? block.text}
        </div>
      ) : null}
    </div>
  );
}

'use client';

import { cn } from '@/lib/utils';
import type { TranscriptSource, TranscriptSourcesBlock } from '@dudousxd/nestjs-agent-react';
import type { ReactNode } from 'react';
import { CheckIcon, DocumentIcon } from './icons';

export interface ChatSourcesProps {
  /** A `sources` block off `item.blocks` — set `sources: true` on the transcript to get them. */
  block: TranscriptSourcesBlock;
  /** A mark per origin — a product logo, an avatar. Falls back to a document glyph. */
  renderSourceIcon?: (source: TranscriptSource) => ReactNode;
  /** Overrides the "Answered from 3 sources" line. */
  renderSummary?: (block: TranscriptSourcesBlock) => ReactNode;
  onSourceClick?: (source: TranscriptSource) => void;
  className?: string;
}

/**
 * What the answer was built from, above the answer. The counts are the retriever's own: how many
 * distinct origins it drew on, and how many passages each contributed.
 */
export function ChatSources({
  block,
  renderSourceIcon,
  renderSummary,
  onSourceClick,
  className,
}: ChatSourcesProps) {
  if (block.sources.length === 0) {
    return null;
  }

  return (
    <section
      data-slot="chat-sources"
      aria-label="Sources for this answer"
      className={cn('rounded-xl border border-border bg-muted/40 p-3', className)}
    >
      <p className="px-1 pb-1 text-xs font-medium text-muted-foreground">
        {renderSummary ? renderSummary(block) : defaultSummary(block)}
      </p>
      <ul className="flex flex-col">
        {block.sources.map((source) => {
          const line = (
            <>
              <CheckIcon className="size-4 shrink-0 text-emerald-600 dark:text-emerald-400" />
              <span className="min-w-0 flex-1 truncate text-sm text-foreground">
                {source.label}
              </span>
              <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
                {source.passageCount === 1 ? '1 passage' : `${source.passageCount} passages`}
              </span>
              <span className="shrink-0 text-muted-foreground [&_svg]:size-4">
                {renderSourceIcon ? renderSourceIcon(source) : <DocumentIcon className="size-4" />}
              </span>
            </>
          );
          return (
            <li key={source.id}>
              {onSourceClick ? (
                <button
                  type="button"
                  onClick={() => onSourceClick(source)}
                  className={cn(
                    'flex w-full items-center gap-2.5 rounded-lg px-1 py-1.5 text-left',
